    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.commProtocolElementEClass, source, new String[]{"documentation", "Description of the protocol elements. These may be frames, signals (which are in turn part of a  frame) or signal groups."});
        this.addAnnotation((ENamedElement)this.getCommProtocolElement_Direction(), source, new String[]{"documentation", "The direction in which the element is sent-\r\ns2r : Sender To Receiver (For Sender-Receiver Communication, e.g. data elements)\r\nr2s: Receiver To Sender (For Sender-Receiver Communication, e.g. Acknowledgements)\r\nc2s: Client to Server (For Client-Server Communication,  \"in\" parameters)\r\ns2c Server to Client (For Client-Server Communication,  \"out\" parameters)"});
        this.addAnnotation((ENamedElement)this.commProtocolFrameRoleEClass, source, new String[]{"documentation", "If the protocol instance uses frame instances as protocol elements, they are specified with this element. This is e.g. the case in protocol ISO 15765-2, where complete frames are used to exchange information between the communication partners."});
        this.addAnnotation((ENamedElement)this.getCommProtocolFrameRole_FrameInstance(), source, new String[]{"documentation", "Reference to the frame instance. Each frame role description refers to exactly one frame instance, but the same signal instance may be included in different role descriptions. The latter is the case, if the same frame instance is e.g. used by different protocols (that then will have additional means to indicate which protocol is active)"});
        this.addAnnotation((ENamedElement)this.getCommProtocolFrameRole_ProtocolElement(), source, new String[]{"documentation", "Reference to the protocol element in the protocol type that is instantiated by this frame role."});
        this.addAnnotation((ENamedElement)this.commProtocolSignalGroupRoleEClass, source, new String[]{"documentation", "If the protocol instance uses signal groups as protocol elements, they are specified with this element."});
        this.addAnnotation((ENamedElement)this.getCommProtocolSignalGroupRole_ProtocolElement(), source, new String[]{"documentation", "Reference to the protocol element in the protocol type that is instantiated by this signalGroup role."});
        this.addAnnotation((ENamedElement)this.getCommProtocolSignalGroupRole_SignalGroupInstance(), source, new String[]{"documentation", "Reference to the signalGroup. Each signalGroup role description refers to exactly one signalGroup, but the same signalGroup may be included in different role descriptions. The latter is the case, if the same signalGroup is e.g. used by different protocols (that then will have additional means to indicate which protocol is active)"});
        this.addAnnotation((ENamedElement)this.commProtocolSignalRoleEClass, source, new String[]{"documentation", "If the protocol instance uses signal instances (in a specific frame instance) as protocol elements, they are specified with this element."});
        this.addAnnotation((ENamedElement)this.getCommProtocolSignalRole_ProtocolElement(), source, new String[]{"documentation", "Reference to the protocol element in the protocol type that is implemented by this signal role."});
        this.addAnnotation((ENamedElement)this.getCommProtocolSignalRole_SignalInstance(), source, new String[]{"documentation", "Reference to the system signal used to transport the communication protocol. Each signal Role Description refers to exactly one system signal, but the same system signal  may be included in different role descriptions. The latter is the case, if the same system signal is e.g. used by different protocols (that then will have additional means to indicate which protocol is active)"});
        this.addAnnotation((ENamedElement)this.commProtocolTypeEClass, source, new String[]{"documentation", "The protocol type description describes all necessary protocol parameters that are the same for all instances of the protocol and that are necessary to configure the protocol.,\r\nThis is e.g.. a generic definition of ISO 15765-2.\r\n"});
        this.addAnnotation((ENamedElement)this.getCommProtocolType_ProtocolElements(), source, new String[]{"documentation", "The communication protocol type description includes at least one protocol element."});
        this.addAnnotation((ENamedElement)this.commProtocolInstanceEClass, source, new String[]{"documentation", "An instance of a communication protocol, used for exchanging information between specific communication partners. This might e.g. be an instance of ISO 15765-2 running between ECU A and ECU B."});
        this.addAnnotation((ENamedElement)this.getCommProtocolInstance_ProtocolFrames(), source, new String[]{"documentation", "The communication protocol instance can uses frames as protocol elements."});
        this.addAnnotation((ENamedElement)this.getCommProtocolInstance_ProtocolSignals(), source, new String[]{"documentation", "The communication protocol instance can uses signals as protocol elements."});
        this.addAnnotation((ENamedElement)this.getCommProtocolInstance_ProtocolSignalGroups(), source, new String[]{"documentation", "The communication protocol instance can uses signal groups as protocol elements."});
        this.addAnnotation((ENamedElement)this.getCommProtocolInstance_ProtocolType(), source, new String[]{"documentation", "reference to the communication protocol that is used in this instance. "});
    }

